package club.sanai.app;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.Build;
import android.provider.Settings;
import android.webkit.WebView;
import android.widget.EditText;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.cert.CertificateFactory;
import java.util.Arrays;
import java.util.Locale;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;

final class UpdateCenter {
    private final Activity a; private final WebView web; private final SharedPreferences p;
    private final ExecutorService worker=Executors.newSingleThreadExecutor(); private boolean busy=false; private boolean pageReady=false; private boolean resumePending=false;
    private static final String HOME="file:///android_asset/index.html";
    private static final int MAX_META=65536, MAX_PATCH=1024*1024, MAX_APK=100*1024*1024;
    UpdateCenter(Activity a,WebView w){this.a=a;web=w;p=a.getSharedPreferences("sanai_update_v1",0);}
    private String repo(){return p.getString("repo","2645chounggs-dot/SANAI-CLUB");}
    private int current() throws Exception {return a.getPackageManager().getPackageInfo(a.getPackageName(),0).versionCode;}
    private String currentName(){try{return a.getPackageManager().getPackageInfo(a.getPackageName(),0).versionName;}catch(Exception e){return "?";}}
    private void message(String s){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("사나이 업데이트 센터").setMessage(s).setPositiveButton("확인",null).show();}
    void open(){if(a.isFinishing())return;String patch=p.getString("patch","").isEmpty()?"없음":"r"+p.getInt("revision",0);new AlertDialog.Builder(a).setTitle("사나이 업데이트 센터 · V"+currentName()+"\n웹 패치: "+patch+" · "+(repo().isEmpty()?"미연결":repo())).setItems(new String[]{"최신 APK 확인","웹 패치 확인 (OTA)","업데이트 채널 설정","자동 확인 "+(p.getBoolean("auto",true)?"끄기":"켜기"),"웹 패치 제거 / 기본 화면 복구"},(d,n)->{if(n==0)check(false,false);else if(n==1)check(true,false);else if(n==2)configure();else if(n==3){p.edit().putBoolean("auto",!p.getBoolean("auto",true)).apply();open();}else rollback();}).setNegativeButton("닫기",null).show();}
    private void configure(){EditText t=new EditText(a);t.setSingleLine(true);t.setHint("GitHub 사용자명/저장소");t.setText(repo());new AlertDialog.Builder(a).setTitle("공식 업데이트 채널").setMessage("공개 GitHub 릴리스의 owner/repo를 입력해라. 서명과 패키지 ID가 기존 앱과 일치해야 설치할 수 있다.").setView(t).setPositiveButton("저장",(d,w)->{String s=t.getText().toString().trim();if(!s.matches("[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]{1,100}")||s.endsWith("/.")||s.endsWith("/..")){message("저장소 주소 형식을 확인해라, BRO.");return;}p.edit().putString("repo",s).remove("lastCheck").apply();open();}).setNegativeButton("취소",null).show();}
    void safeMode(){p.edit().remove("patch").remove("patchMeta").remove("patchSig").apply();message("웹 패치를 제거했다. 기본 화면으로 복구한다, BRO.");}
    void onResume(){if(resumePending&&a.getPackageManager().canRequestPackageInstalls()){resumePending=false;installVerified();}}
    void onPageReady(){pageReady=true;applyStoredPatch();if(!repo().isEmpty()&&p.getBoolean("auto",true)&&System.currentTimeMillis()-p.getLong("lastCheck",0)>86400000L){p.edit().putLong("lastCheck",System.currentTimeMillis()).apply();check(false,true);}}
    private void rollback(){new AlertDialog.Builder(a).setTitle("기본 화면으로 복귀").setMessage("웹 패치만 제거한다. 운동 기록은 건드리지 않는다.").setPositiveButton("복구",(d,w)->{p.edit().remove("patch").remove("patchMeta").remove("patchSig").apply();web.reload();}).setNegativeButton("취소",null).show();}
    private byte[] fetch(String url,int limit)throws Exception{URL u=new URL(url);for(int count=0;count<6;count++){if(!"https".equals(u.getProtocol())||u.getUserInfo()!=null)throw new SecurityException("HTTPS required");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(25000);try{int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");if(location==null)throw new IOException("Redirect");u=new URL(u,location);continue;}if(code!=200)throw new IOException("HTTP "+code);if(c.getContentLengthLong()>limit)throw new IOException("Too large");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Too large");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}throw new IOException("Redirect limit");}
    private android.content.pm.Signature[] certs(PackageInfo info){if(Build.VERSION.SDK_INT>=28)return info.signingInfo==null?new android.content.pm.Signature[0]:info.signingInfo.getApkContentsSigners();return info.signatures;}
    private int flags(){return Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;}
    private android.content.pm.Signature[] ownCerts()throws Exception{return certs(a.getPackageManager().getPackageInfo(a.getPackageName(),flags()));}
    private void verify(byte[] data,byte[] sig)throws Exception{android.content.pm.Signature[] cert=ownCerts();if(cert.length!=1)throw new SecurityException("Signer count");PublicKey key=CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(cert[0].toByteArray())).getPublicKey();java.security.Signature verifier=java.security.Signature.getInstance("SHA256withRSA");verifier.initVerify(key);verifier.update(data);if(!verifier.verify(sig))throw new SecurityException("Manifest signature");}
    private String sha(byte[] b)throws Exception{byte[] h=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder s=new StringBuilder();for(byte v:h)s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
    private JSONObject metadata(byte[] raw,byte[] sig,String kind)throws Exception{verify(raw,sig);JSONObject j=new JSONObject(new String(raw,StandardCharsets.UTF_8));if(j.getInt("schema")!=1||!a.getPackageName().equals(j.getString("package"))||!kind.equals(j.getString("kind"))||!j.getString("sha256").matches("[0-9a-f]{64}"))throw new SecurityException("Metadata");return j;}
    private String base(String r,boolean ota){return "https://github.com/"+r+"/releases/"+(ota?"download/ota-channel/":"latest/download/");}
    private void check(boolean ota,boolean quiet){if(busy)return;String r=repo();if(r.isEmpty()){if(!quiet)configure();return;}busy=true;worker.execute(()->{try{String b=base(r,ota);byte[] raw=fetch(b+(ota?"ota.json":"update.json"),MAX_META), sig=fetch(b+(ota?"ota.sig":"update.sig"),8192);JSONObject j=metadata(raw,sig,ota?"ota":"apk");int installed=current();boolean newer=ota?j.getInt("nativeVersion")==installed&&j.getInt("revision")>p.getInt("revision_"+installed,0):j.getInt("versionCode")>installed;a.runOnUiThread(()->{busy=false;if(!r.equals(repo())||a.isFinishing())return;if(!newer){if(!quiet)message("지금 버전에 적용할 새 업데이트가 없다, BRO.");else if(!ota)check(true,true);return;}new AlertDialog.Builder(a).setTitle(ota?"새 웹 패치 발견":"새 APK V"+j.optString("versionName")).setMessage(j.optString("notes","새로운 진화가 준비됐다.")+"\n기록은 초기화하지 않는다. 설치 전 백업을 권장한다.").setPositiveButton(ota?"패치 적용":"다운로드",(d,w)->download(r,ota,raw,sig,j)).setNegativeButton("나중에",null).show();});}catch(Exception e){a.runOnUiThread(()->{busy=false;if(!quiet)message("업데이트를 확인하지 못했다. 채널 주소·릴리스·서명을 확인해라, BRO. ("+e.getClass().getSimpleName()+")");else if(!ota)check(true,true);});}});}
    private void download(String r,boolean ota,byte[] raw,byte[] sig,JSONObject j){if(busy)return;busy=true;worker.execute(()->{try{if(!r.equals(repo()))throw new SecurityException("Channel changed");byte[] payload=fetch(base(r,ota)+(ota?"patch.js":"SANAI.apk"),ota?MAX_PATCH:MAX_APK);if(!sha(payload).equals(j.getString("sha256")))throw new SecurityException("Hash");if(ota){int v=current(),rev=j.getInt("revision");if(v!=j.getInt("nativeVersion")||rev<=p.getInt("revision_"+v,0))throw new SecurityException("Version");p.edit().putString("patch",android.util.Base64.encodeToString(payload,2)).putString("patchMeta",android.util.Base64.encodeToString(raw,2)).putString("patchSig",android.util.Base64.encodeToString(sig,2)).putInt("revision",rev).putInt("revision_"+v,rev).commit();a.runOnUiThread(()->{busy=false;web.reload();message("웹 패치를 검증하고 저장했다. 기본 화면 복구는 업데이트 센터에서 가능하다.");});}else{File f=new File(a.getCacheDir(),"verified-release.apk");try(FileOutputStream out=new FileOutputStream(f)){out.write(payload);}if(!validApk(f,j.getInt("versionCode"))){f.delete();throw new SecurityException("APK signer/version");}p.edit().putInt("pendingVersion",j.getInt("versionCode")).putString("pendingHash",j.getString("sha256")).apply();a.runOnUiThread(()->{busy=false;installVerified();});}}catch(Exception e){a.runOnUiThread(()->{busy=false;message("검증 실패. 설치하지 않았다, BRO. ("+e.getClass().getSimpleName()+")");});}});}
    private boolean validApk(File f,int expected)throws Exception{PackageInfo info=a.getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),flags());return info!=null&&a.getPackageName().equals(info.packageName)&&info.versionCode==expected&&expected>current()&&Arrays.equals(ownCerts(),certs(info));}
    private void installVerified(){if(busy)return;if(!a.getPackageManager().canRequestPackageInstalls()){resumePending=true;new AlertDialog.Builder(a).setTitle("APK 설치 권한").setMessage("Android 설정에서 이 앱의 출처 허용을 켠 다음 돌아와라. 설치는 직접 승인해야 한다.").setPositiveButton("설정 열기",(d,w)->{try{a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));}catch(Exception e){resumePending=false;message("설정에서 설치 권한을 허용해라.");}}).setNegativeButton("취소",(d,w)->resumePending=false).show();return;}busy=true;worker.execute(()->{try{File f=new File(a.getCacheDir(),"verified-release.apk");String hash=sha(java.nio.file.Files.readAllBytes(f.toPath()));if(!hash.equals(p.getString("pendingHash",""))||!validApk(f,p.getInt("pendingVersion",0)))throw new SecurityException("APK changed");a.runOnUiThread(()->{busy=false;try{Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://club.sanai.app.updates/release.apk"),"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(i);}catch(Exception e){message("Android 설치 화면을 열지 못했다.");}});}catch(Exception e){a.runOnUiThread(()->{busy=false;message("설치 파일 검증 실패. 다시 다운로드해라.");});}});}
    private void applyStoredPatch(){if(!pageReady||!HOME.equals(web.getUrl()))return;String stored=p.getString("patch","");if(stored.isEmpty())return;try{byte[] payload=android.util.Base64.decode(stored,2);JSONObject j=metadata(android.util.Base64.decode(p.getString("patchMeta",""),2),android.util.Base64.decode(p.getString("patchSig",""),2),"ota");if(j.getInt("nativeVersion")!=current()){p.edit().remove("patch").remove("patchMeta").remove("patchSig").apply();return;}if(!sha(payload).equals(j.getString("sha256")))throw new SecurityException("Hash");web.evaluateJavascript(new String(payload,StandardCharsets.UTF_8),null);}catch(Exception e){p.edit().remove("patch").remove("patchMeta").remove("patchSig").apply();}}
}
